let m:integer = UInt(CRm[0] :: op2[2:0]);

if !IsFeatureImplemented(FEAT_AMUv1p1) then
    Undefined();
elsif m >= NUM_AMU_CG1_MONITORS then
    Undefined();
elsif !IsG1ActivityMonitorOffsetImplemented(m) then
    Undefined();
elsif HaveEL(EL3) && PSTATE.EL == EL2 && EL3SDDUndefPriority() && CPTR_EL3().TAM == '1' then
    Undefined();
elsif HaveEL(EL3) && PSTATE.EL == EL2 && EL3SDDUndefPriority() && SCR_EL3().AMVOFFEN == '0' then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EffectiveHCR_EL2_NVx() IN {'1x1'} then
        X{64}(t) = NVMem(0xA80 + (8 * m));
    elsif EffectiveHCR_EL2_NVx() IN {'xx1'} then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        Undefined();
    end;
elsif PSTATE.EL == EL2 then
    if HaveEL(EL3) && SCR_EL3().AMVOFFEN == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    elsif HaveEL(EL3) && CPTR_EL3().TAM == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        X{64}(t) = AMEVCNTVOFF1_EL2(m);
    end;
elsif PSTATE.EL == EL3 then
    X{64}(t) = AMEVCNTVOFF1_EL2(m);
end;

let m:integer = UInt(CRm[0] :: op2[2:0]);

if !IsFeatureImplemented(FEAT_AMUv1p1) then
    Undefined();
elsif m >= NUM_AMU_CG1_MONITORS then
    Undefined();
